import DatePicker from "@marko-ui/shadcn/ui/date-picker/date-picker.marko";

static const focusedValue = "2026-08-15";

<DatePicker defaultFocusedValue=focusedValue/>

import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";
import Popover from "@marko-ui/shadcn/ui/popover/popover.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";
import Calendar from "@marko-ui/shadcn/ui/calendar/calendar.marko";

static function formatDate(date?: { year: number; month: number; day: number }) {
  if (!date) return undefined;
  return new Date(date.year, date.month - 1, date.day).toLocaleDateString("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
  });
}

<let/value=[] as { year: number; month: number; day: number }[]/>

<Field class="mx-auto w-44">
  <FieldLabel for="date-picker-simple">Date</FieldLabel>
  <Popover class="w-auto p-0">
    <@trigger|props|>
      <Button type="button" ...props variant="outline" id="date-picker-simple" class="justify-start font-normal">
        <if=value[0]>
          ${formatDate(value[0])}
        </if>
        <else>
          <span>Pick a date</span>
        </else>
      </Button>
    </@trigger>
    <Calendar
      value=value
      valueChange=(next) => { value = next; }
    />
  </Popover>
</Field>

import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";
import Popover from "@marko-ui/shadcn/ui/popover/popover.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";
import Calendar from "@marko-ui/shadcn/ui/calendar/calendar.marko";
import Icon from "@marko-ui/shadcn/ui/icon/icon.marko";

static function formatDate(date: { year: number; month: number; day: number }) {
  return new Date(date.year, date.month - 1, date.day).toLocaleDateString("en-US", {
    year: "numeric",
    month: "short",
    day: "2-digit",
  });
}

<const/fromDate={ year: 2026, month: 1, day: 20 }/>
<const/toDate={ year: 2026, month: 2, day: 9 }/>

<let/value=[fromDate, toDate]/>

<Field class="mx-auto w-60">
  <FieldLabel for="date-picker-range">Date Picker Range</FieldLabel>
  <Popover class="w-auto p-0">
    <@trigger|props|>
      <Button type="button" ...props variant="outline" id="date-picker-range" class="justify-start px-2.5 font-normal">
        <Icon name="Calendar" data-icon="inline-start"/>
        <if=value[0]>
          <if=value[1]>
            ${formatDate(value[0])} - ${formatDate(value[1])}
          </if>
          <else>
            ${formatDate(value[0])}
          </else>
        </if>
        <else>
          <span>Pick a date</span>
        </else>
      </Button>
    </@trigger>
    <Calendar
      selectionMode="range"
      numOfMonths=2
      value=value
      valueChange=(next) => { value = next; }
    />
  </Popover>
</Field>

import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";
import Popover from "@marko-ui/shadcn/ui/popover/popover.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";
import Calendar from "@marko-ui/shadcn/ui/calendar/calendar.marko";

<let/open=false/>
<let/value=[] as { year: number; month: number; day: number }[]/>

<Field class="mx-auto w-44">
  <FieldLabel for="date">Date of birth</FieldLabel>
  <Popover open=open openChange=(next) => { open = next; } class="w-auto overflow-hidden p-0">
    <@trigger|props|>
      <Button type="button" ...props variant="outline" id="date" class="justify-start font-normal">
        <if=value[0]>
          ${new Date(value[0].year, value[0].month - 1, value[0].day).toLocaleDateString()}
        </if>
        <else>
          Select date
        </else>
      </Button>
    </@trigger>
    <Calendar
      captionLayout="dropdown"
      value=value
      valueChange=(next) => {
        value = next;
        open = false;
      }
    />
  </Popover>
</Field>

import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";
import InputGroup from "@marko-ui/shadcn/ui/input-group/input-group.marko";
import InputGroupInput from "@marko-ui/shadcn/ui/input-group/input.marko";
import InputGroupAddon from "@marko-ui/shadcn/ui/input-group/addon.marko";
import InputGroupButton from "@marko-ui/shadcn/ui/input-group/button.marko";
import Popover from "@marko-ui/shadcn/ui/popover/popover.marko";
import Calendar from "@marko-ui/shadcn/ui/calendar/calendar.marko";
import Icon from "@marko-ui/shadcn/ui/icon/icon.marko";

static function formatDate(date?: { year: number; month: number; day: number }) {
  if (!date) return "";
  return new Date(date.year, date.month - 1, date.day).toLocaleDateString("en-US", {
    day: "2-digit",
    month: "long",
    year: "numeric",
  });
}

static function parseInput(text: string) {
  const date = new Date(text);
  if (isNaN(date.getTime())) return undefined;
  return { year: date.getFullYear(), month: date.getMonth() + 1, day: date.getDate() };
}

<const/initial=(parseInput("2025-06-01")!)/>

<let/open=false/>
<let/value=[initial]/>
<let/text=formatDate(initial)/>

<Field class="mx-auto w-48">
  <FieldLabel for="date-required">Subscription Date</FieldLabel>
  <InputGroup>
    <InputGroupInput
      id="date-required"
      value=text
      placeholder="June 01, 2025"
      valueChange=(next) => {
        text = next ?? "";
        const parsed = parseInput(text);
        if (parsed) value = [parsed];
      }
      onKeyDown(event: KeyboardEvent) {
        if (event.key === "ArrowDown") {
          event.preventDefault();
          open = true;
        }
      }
    />
    <InputGroupAddon align="inline-end">
      <Popover open=open openChange=(next) => { open = next; } class="w-auto overflow-hidden p-0">
        <@trigger|props|>
          <InputGroupButton ...props id="date-picker" variant="ghost" size="icon-xs" aria-label="Select date">
            <Icon name="Calendar"/>
            <span class="sr-only">Select date</span>
          </InputGroupButton>
        </@trigger>
        <Calendar
          value=value
          valueChange=(next) => {
            value = next;
            text = formatDate(next[0]);
            open = false;
          }
        />
      </Popover>
    </InputGroupAddon>
  </InputGroup>
</Field>

import FieldGroup from "@marko-ui/shadcn/ui/field/field-group.marko";
import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";
import TextInput from "@marko-ui/shadcn/ui/input/input.marko";
import Popover from "@marko-ui/shadcn/ui/popover/popover.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";
import Calendar from "@marko-ui/shadcn/ui/calendar/calendar.marko";
import Icon from "@marko-ui/shadcn/ui/icon/icon.marko";

static function formatDate(date?: { year: number; month: number; day: number }) {
  if (!date) return undefined;
  return new Date(date.year, date.month - 1, date.day).toLocaleDateString("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
  });
}

<let/open=false/>
<let/value=[] as { year: number; month: number; day: number }[]/>

<FieldGroup class="mx-auto max-w-xs flex-row">
  <Field>
    <FieldLabel for="date-picker-optional">Date</FieldLabel>
    <Popover open=open openChange=(next) => { open = next; } class="w-auto overflow-hidden p-0">
      <@trigger|props|>
        <Button type="button" ...props variant="outline" id="date-picker-optional" class="w-32 justify-between font-normal">
          <if=value[0]>
            ${formatDate(value[0])}
          </if>
          <else>
            Select date
          </else>
          <Icon name="ChevronDown" data-icon="inline-end"/>
        </Button>
      </@trigger>
      <Calendar
        captionLayout="dropdown"
        value=value
        valueChange=(next) => {
          value = next;
          open = false;
        }
      />
    </Popover>
  </Field>
  <Field class="w-32">
    <FieldLabel for="time-picker-optional">Time</FieldLabel>
    <TextInput
      type="time"
      id="time-picker-optional"
      step="1"
      value="10:30:00"
      class="appearance-none bg-background [&::-webkit-calendar-picker-indicator]:hidden [&::-webkit-calendar-picker-indicator]:appearance-none"
    />
  </Field>
</FieldGroup>
